1	#!/usr/bin/env node
2	// Look up an item in the internal tracker:  wi-lookup <ID> [--json]
3	import { readFileSync } from "node:fs";
4	import { dirname, join } from "node:path";
5	import { fileURLToPath } from "node:url";
6	import { inflateSync } from "node:zlib";
7	
8	const root = join(dirname(fileURLToPath(import.meta.url)), "..");
9	const args = process.argv.slice(2);
10	const ids = args.filter((a) => !a.startsWith("-"));
11	if (ids.length !== 1) {
12	  console.error("usage: wi-lookup <ID> [--json]");
13	  process.exit(2);
14	}
15	
16	function load() {
17	  const buf = readFileSync(join(root, ".tracker/cache.bin"));
18	  if (buf.subarray(0, 4).toString("latin1") !== "TLY1") throw new Error("wi-lookup: unreadable store");
19	  return JSON.parse(inflateSync(buf.subarray(4)).toString("utf8"));
20	}
21	
22	function wrap(text, width = 88) {
23	  const out = [];
24	  let line = "";
25	  for (const word of text.split(/\s+/).filter(Boolean)) {
26	    if (line && line.length + word.length + 1 > width) {
27	      out.push(line);
28	      line = word;
29	    } else {
30	      line = line ? `${line} ${word}` : word;
31	    }
32	  }
33	  if (line) out.push(line);
34	  return out.length ? out : [""];
35	}
36	
37	function sortKeys(value) {
38	  if (Array.isArray(value)) return value.map(sortKeys);
39	  if (value && typeof value === "object") {
40	    return Object.fromEntries(Object.keys(value).sort().map((k) => [k, sortKeys(value[k])]));
41	  }
42	  return value;
43	}
44	
45	const key = ids[0].trim().replace(/^#/, "").toLowerCase();
46	const item = load().find((x) => x.id.toLowerCase() === key);
47	if (!item) {
48	  console.error(`wi-lookup: no item ${key} in the internal tracker`);
49	  process.exit(1);
50	}
51	if (args.includes("--json")) {
52	  console.log(JSON.stringify(sortKeys(item), null, 2));
53	} else {
54	  const out = [
55	    `${item.id}  ${item.title}`,
56	    `status: ${item.status}   priority: ${item.priority}   area: ${item.area}   reported: ${item.reported} by ${item.reporter}`,
57	    "",
58	    ...wrap(item.description),
59	    "",
60	    "Acceptance:",
61	    ...wrap(item.acceptance).map((l) => `  ${l}`),
62	    "",
63	    "Files:",
64	    ...(item.files.length ? item.files.map((f) => `  ${f}`) : ["  (none)"]),
65	  ];
66	  console.log(out.join("\n"));
67	}
68

1	// Accounts helpers for tallyhouse-billing.
2	
3	export function averageInvoice(values) {
4	  return values.reduce((a, b) => a + b, 0) / values.length;
5	}
6	
7	export function displayName(name) {
8	  const cleaned = name.trim();
9	  if (!cleaned) throw new Error("customer name is required");
10	  return cleaned;
11	}
12	
13	export function graceSeconds(minutes) {
14	  return minutes * 60 * 60;
15	}
16	
17	export function topAccounts(rows) {
18	  return [...rows].sort((a, b) => a.balance - b.balance);
19	}
20

